t ditambahkan oleh tim setelah verifikasi.</p><div class="alumni-form-grid"><?= $form->field($model,'publication_title')->textInput(['placeholder'=>'Judul karya / skripsi / penelitian'])->label('Judul Karya') ?><?= $form->field($model,'publication_type')->dropDownList(AlumniPublication::TYPES,['prompt'=>'Pilih jenis'])->label('Jenis Karya') ?><?= $form->field($model,'publication_year')->input('number')->label('Tahun') ?><?= $form->field($model,'publication_url')->textInput(['placeholder'=>'Tautan repository / publikasi'])->label('Tautan') ?></div><?= $form->field($model,'publication_about_service')->checkbox()->label('Karya ini membahas pengalaman atau pengabdian Sumut Mengajar') ?><hr><?= $form->field($model,'consent_public')->checkbox()->label('Saya setuju data profil, riwayat pengabdian, karier, dan karya yang saya isi dapat ditampilkan pada halaman Alumni Sumut Mengajar setelah diverifikasi. Nomor WhatsApp tidak akan ditampilkan ke publik.') ?><button class="btn-primary-gsm" type="submit">Kirim Data Alumni →</button><?php ActiveForm::end(); ?></div>
